/*
  Full India + China location-catalog reset (PostgreSQL / pgAdmin compatible)

  Dataset: countries-states-cities-database, release v3.2-export.3
  Source: https://github.com/dr5hn/countries-states-cities-database/releases/download/v3.2-export.3/json-countries%2Bstates%2Bcities.json.gz
  License: Open Database License (ODbL). Retain this attribution on redistribution.

  Result: India (36 states/UTs, 4199 cities) + China
  (34 regions, 4134 cities). Macau SAR has no District in
  the source release, so the script deliberately includes the fallback District Macao.

  WARNING: This is a full Country / State / District reset. It also clears the country
  reference records that block those FKs: District, ComplianceRule,
  CountryIdentityRule, CountryStatutoryRule, StatutoryType, TaxSystemMaster and
  TaxRegimeMaster. Host tables are not deleted. It aborts if institution/user data still
  exists, so run ClearInstitutionDependencies.sql first.

  Run once with ExecuteReset = FALSE, take a backup, then change only that value to
  TRUE and execute the entire file as one batch.
*/

BEGIN;
SET LOCAL lock_timeout = '15s';
SET LOCAL statement_timeout = '180s';

CREATE TEMP TABLE location_reset_config ("ExecuteReset" boolean NOT NULL) ON COMMIT DROP;
-- CHANGE ONLY THIS LINE FOR THE ACTUAL RESET.
INSERT INTO location_reset_config ("ExecuteReset") VALUES (FALSE);

CREATE TEMP TABLE full_location_seed
(
    "CountryCode" character varying(10) NOT NULL,
    "StateSort" integer NOT NULL,
    "StateName" character varying(100) NOT NULL,
    "DistrictName" character varying(100) NOT NULL
) ON COMMIT DROP;

INSERT INTO full_location_seed ("CountryCode", "StateSort", "StateName", "DistrictName")
