    ('CN', 70, 'Zhejiang', 'Zhaobaoshan'),
    ('CN', 70, 'Zhejiang', 'Zhenhai'),
    ('CN', 70, 'Zhejiang', 'Zhicheng'),
    ('CN', 70, 'Zhejiang', 'Zhoushan'),
    ('CN', 70, 'Zhejiang', 'Zhuji'),
    ('CN', 70, 'Zhejiang', 'Zhuji');

DO
$$
DECLARE
    v_execute_reset boolean;
    v_count bigint;
    v_dependency record;
    v_reference_table text;
    v_sequence text;
BEGIN
    SELECT "ExecuteReset" INTO v_execute_reset FROM pg_temp.location_reset_config;

    IF (SELECT COUNT(*) FROM pg_temp.full_location_seed) <> 8333 THEN
        RAISE EXCEPTION 'Source District-count validation failed before reset.';
    END IF;

    IF (SELECT COUNT(*) FROM (SELECT "CountryCode", "StateName" FROM pg_temp.full_location_seed GROUP BY "CountryCode", "StateName") states) <> 70 THEN
        RAISE EXCEPTION 'Source state-count validation failed before reset.';
    END IF;

    IF NOT v_execute_reset THEN
        RAISE NOTICE 'PREVIEW ONLY: no rows were deleted. Change ExecuteReset to TRUE only after backup/review.';
        RETURN;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended('skolenza.location.full.india-china.reset', 0));

    -- This script intentionally refuses to erase institution/user data as part of a
    -- location-master reset. Institution cleanup must succeed first.
    FOREACH v_reference_table IN ARRAY ARRAY[
        'Institution', 'StaffMember', 'Campus', 'StaffMemberTaxProfile',
        'SalaryComponentMaster', 'TaxRule', 'TaxSlab'
    ]
    LOOP
        EXECUTE format('SELECT COUNT(*) FROM skolenza.%I', v_reference_table) INTO v_count;
        IF v_count > 0 THEN
            RAISE EXCEPTION 'Country reset stopped: skolenza.% still has % row(s). Run institution cleanup first.', v_reference_table, v_count;
        END IF;
    END LOOP;

    -- Fail closed when schema adds a new Country/State/District foreign key that
    -- is not reviewed in this script's ordered cleanup list.
    FOR v_dependency IN
        SELECT DISTINCT source.relname AS table_name
        FROM pg_constraint fk
        JOIN pg_class target ON target.oid = fk.confrelid
        JOIN pg_namespace target_schema ON target_schema.oid = target.relnamespace
        JOIN pg_class source ON source.oid = fk.conrelid
        JOIN pg_namespace source_schema ON source_schema.oid = source.relnamespace
        WHERE fk.contype = 'f'
          AND target_schema.nspname = 'skolenza'
          AND source_schema.nspname = 'skolenza'
          AND target.relname IN ('Country', 'State', 'District')
          AND source.relname NOT IN
          (
              'District', 'State', 'District', 'ComplianceRule',
              'CountryIdentityRule', 'CountryStatutoryRule', 'StatutoryType',
              'TaxSystemMaster', 'TaxRegimeMaster', 'Campus', 'StaffMember',
              'StaffMemberTaxProfile', 'SalaryComponentMaster',
              'TaxRule', 'TaxSlab'
          )
    LOOP
        EXECUTE format('SELECT COUNT(*) FROM skolenza.%I', v_dependency.table_name) INTO v_count;
        IF v_count > 0 THEN
            RAISE EXCEPTION 'Country reset stopped: unhandled populated dependency skolenza.%.', v_dependency.table_name;
        END IF;
    END LOOP;

    LOCK TABLE
        skolenza."Country", skolenza."State", skolenza."District", skolenza."District",
        skolenza."ComplianceRule", skolenza."CountryIdentityRule",
        skolenza."CountryStatutoryRule", skolenza."StatutoryType",
        skolenza."TaxSystemMaster", skolenza."TaxRegimeMaster"
    IN ACCESS EXCLUSIVE MODE;

    -- Delete children before Country / State / District parents.
    DELETE FROM skolenza."TaxRegimeMaster";
    DELETE FROM skolenza."ComplianceRule";
    DELETE FROM skolenza."CountryStatutoryRule";
    DELETE FROM skolenza."CountryIdentityRule";
    DELETE FROM skolenza."District";
    DELETE FROM skolenza."District";
    DELETE FROM skolenza."TaxSystemMaster";
    DELETE FROM skolenza."StatutoryType";
    DELETE FROM skolenza."State";
    DELETE FROM skolenza."Country";

    FOREACH v_reference_table IN ARRAY ARRAY[
        'Country', 'State', 'District', 'District', 'ComplianceRule',
        'CountryIdentityRule', 'CountryStatutoryRule', 'StatutoryType',
        'TaxSystemMaster', 'TaxRegimeMaster'
    ]
    LOOP
        SELECT pg_get_serial_sequence(format('skolenza.%I', v_reference_table), 'Id') INTO v_sequence;
        IF v_sequence IS NOT NULL THEN
            EXECUTE format('ALTER SEQUENCE %s RESTART WITH 1', v_sequence);
        END IF;
    END LOOP;

    INSERT INTO skolenza."Country" ("CountryName", "CountryCode", "STDCode", "IsActive")
    VALUES ('India', 'IN', '+91', TRUE), ('China', 'CN', '+86', TRUE);

    INSERT INTO skolenza."State" ("CountryId", "StateName", "IsActive")
    SELECT country."Id", seed."StateName", TRUE
    FROM
    (
        SELECT "CountryCode", "StateName", MIN("StateSort") AS "StateSort"
        FROM pg_temp.full_location_seed
        GROUP BY "CountryCode", "StateName"
    ) seed
    JOIN skolenza."Country" country ON country."CountryCode" = seed."CountryCode"
    ORDER BY seed."StateSort";

    INSERT INTO skolenza."District" ("StateId", "DistrictName", "IsActive")
    SELECT state."Id", seed."DistrictName", TRUE
    FROM pg_temp.full_location_seed seed
    JOIN skolenza."Country" country ON country."CountryCode" = seed."CountryCode"
    JOIN skolenza."State" state ON state."CountryId" = country."Id" AND state."StateName" = seed."StateName"
    ORDER BY seed."StateSort", seed."DistrictName";

    IF (SELECT COUNT(*) FROM skolenza."Country") <> 2
       OR (SELECT COUNT(*) FROM skolenza."State") <> 70
       OR (SELECT COUNT(*) FROM skolenza."District") <> 8333 THEN
        RAISE EXCEPTION 'Location reset post-seed validation failed. Transaction will roll back.';
    END IF;

    RAISE NOTICE 'India/China reset complete: % states and % cities.', 70, 8333;
END;
$$;

SELECT c."CountryCode", c."CountryName", COUNT(DISTINCT s."Id") AS "StateCount", COUNT(District."Id") AS "DistrictCount"
FROM skolenza."Country" c
LEFT JOIN skolenza."State" s ON s."CountryId" = c."Id"
LEFT JOIN skolenza."District" District ON District."StateId" = s."Id"
WHERE c."CountryCode" IN ('IN', 'CN')
GROUP BY c."CountryCode", c."CountryName"
ORDER BY c."CountryCode";

COMMIT;
